    "「備份存檔」會把這個世界存成一個檔案放到你的裝置上；換手機、清除瀏覽器資料之前，或想把世界分享給朋友時使用。": "\"Yedek kaydet\", bu dünyayı cihazınıza dosya olarak kaydeder; telefon değiştirmeden, tarayıcı verilerini silmeden önce veya dünyanızı arkadaşlarınızla paylaşmak istediğinizde kullanın.",
    "「如果」平行世界：{0}。": "\"Ya olsaydı?\" paralel dünyası: {0}.",
    "「沒有你的世界」：同一個種子、不重播你的介入重跑一次，比較哪個世界先毀滅": "\"Sensiz dünya\": aynı tohumla müdahalelerin olmadan yeniden oynat ve hangi dünyanın önce bittiğini gör",
    "「沒有國家」與「允許戰爭」互相衝突：沒有國家時不存在國家間戰爭。": "\"Devlet yok\", \"Savaşa izin var\" ile çelişiyor: devlet yoksa devletler arası savaş da olmaz.",
    "「沒有貨幣」與「存在資本主義」互相衝突：資本主義需要以貨幣計價的資本市場。": "\"Para yok\", \"Kapitalizm var\" ile çelişiyor: kapitalizm, parayla fiyatlanan sermaye piyasalarına ihtiyaç duyar.",
    "「直接死亡」是發生當下的死亡；「之後的死亡」是它留下的長期影響（臨界點的額外升溫、核子寒冬）在之後每年多造成的死亡，依公式拆分。": "\"Doğrudan ölümler\" o andaki ölümlerdir; \"sonraki ölümler\" ise kalıcı etkilerin (devrilme noktalarından ek ısınma, nükleer kış) sonraki yıllarda yol açtığı ek ölümlerdir ve formülle ayrılır.",
    "「讀取備份」選那個檔案就能回到這個世界。": "Bu dünyaya dönmek için \"Yedeği yükle\"de o dosyayı seçin.",
    "」可以追查），每場災難都是事件，可以用「如果？": "\" ile izlenebilir) ve her felaket \"Ya olsaydı?",
    "」平行世界重跑時，也會在同一個時間重播這次干預。": "\" paralel dünyası yeniden oynatıldığında bu müdahale aynı anda tekrarlanır.",
    "」平行世界重跑時，也會在同一個月份重播這次干預。": "\" paralel dünyası yeniden oynatıldığında bu müdahale aynı ayda tekrarlanır.",
    "」改寫。": "\" henüz yok.",
    "」改寫它沒有發生。": "\" ile hiç olmamış gibi yeniden yazılabilen bir olaydır.",
    "」改寫（每一項都能點開追查原因）": "\" yeniden yazımları (her biri dokunularak nedenleri izlenebilir)",
    "」改寫，看看世界會在什麼時候、因為什麼終結。": "\" ile yeniden yaz ve dünyanın ne zaman ve neden bittiğini gör.",
    "」與完整紀錄）。": "\" ve tam kayıt).",
